'use strict';
let personalItems=[],personalReady=false,personalError='',mindText='',mindTitle='',mindBucket='Unsorted',mindEditing=null,mindQuery='',mindFilter='any',mindBusy=false,lastPersonalRemoval=null,lastPersonalGroup=[];
let shelfType='words',shelfTitle='',shelfText='',shelfLink='',shelfNeed='',shelfFile=null,shelfBusy=false;
const personalURLs=new Map();
const personalChannel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('antar-personal-changes'):null;
const personalId=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2);
async function refreshPersonal(notify=false){try{personalItems=await readPersonal();personalReady=true;personalError='';if(notify)personalChannel?.postMessage('changed');if((['mind','comfort','support','home','mind-map','experiments','preferences'].includes(route)||route.startsWith('thought/')))render(true)}catch{personalError='Your saved shelf could not be read. Check browser storage or close other Antar tabs. Existing data has not been replaced.';if((['mind','comfort','home','mind-map','experiments','preferences'].includes(route)||route.startsWith('thought/')))render(true)}}
personalChannel?.addEventListener('message',()=>refreshPersonal());
window.addEventListener('load',()=>refreshPersonal());
function personalNotice(){return `<p class="note">Saved only on this browser/device, without app encryption or account sync. Nothing here is sent to AI. Clearing website data can remove it. Export important memories.</p>${personalError?`<p class="warning" role="status">${esc(personalError)}</p>`:''}`}
function personalBackupControls(){return `${lastPersonalRemoval?'<button class="secondary" data-personal="undo">Undo last removal</button>':''}<details><summary>Backup &amp; local storage</summary>${personalNotice()}<button class="secondary" data-personal="export">Download my personal backup</button><p class="small">Includes saved thoughts, connections, experiments, comfort items, and original photo/audio files in a personal JSON file. Check-in history has its own export in My month. Keep backups private.</p><button class="text-btn" data-personal="refresh">Refresh saved items</button></details>`}
function mindCards(){const items=AntarPersonal.search(personalItems.filter(x=>x.kind==='thought'),mindQuery,mindFilter);return `<p class="small" role="status">${items.length} saved ${items.length===1?'thought':'thoughts'} in this view.</p>${items.map(x=>`<article class="mind-card"><div class="inline-row"><span class="tag">${esc(x.bucket)}</span>${x.pinned?'<span class="small">Pinned by you</span>':''}</div><h2><a href="#thought/${encodeURIComponent(x.id)}">${esc(x.title||'A thought, as it came')}</a></h2><p class="mind-body">${esc(x.text)}</p><p class="small">${new Date(x.createdAt).toLocaleString('en-IN')}</p><div class="chips"><button class="text-btn" data-mind-edit="${esc(x.id)}">Open &amp; edit</button><button class="text-btn" data-personal-pin="${esc(x.id)}">${x.pinned?'Unpin':'Pin'}</button><button class="text-btn" data-connect-from="${esc(x.id)}">Connect</button><button class="text-btn" data-revisit-toggle="${esc(x.id)}">${x.revisit?'Remove from resurfacing':'Choose for resurfacing'}</button><button class="text-btn" data-personal-remove="${esc(x.id)}">Remove</button></div></article>`).join('')||'<p class="empty">No thoughts in this view. You don’t need to fill this space.</p>'}`}
function secondMind(){return `<a class="install-link" href="#home">‹ Home</a>${livingTabs('mind')}<p class="greeting">Second mind</p><h1>Sab yahin rakh do.</h1><p class="sub">A messy thought, a half-made plan, something you can’t stop replaying. Samajhna ya sort karna abhi zaroori nahi.</p>${resurfaceCard()}<label class="field" for="mind-text">What’s taking up space?</label><textarea id="mind-text" maxlength="12000" placeholder="Abhi mere dimaag mein…">${esc(mindText)}</textarea><details><summary>A title or place for it? Optional.</summary><label class="field" for="mind-title">A few words to find it later</label><input id="mind-title" type="text" maxlength="100" value="${esc(mindTitle)}"><label class="field" for="mind-bucket">Where would you put it?</label><select id="mind-bucket" class="section-select">${AntarPersonal.buckets.map(b=>`<option ${mindBucket===b?'selected':''}>${b}</option>`).join('')}</select><p class="small">“Can wait” adds no reminder. These are your choices, not an analysis.</p></details><button class="primary" data-personal="save-thought" ${mindBusy||!personalReady?'disabled':''}>${mindBusy?'Saving…':mindEditing?'Save my changes':'Save to my second mind'}</button><button class="text-btn" data-personal="release-draft">${mindEditing?'Close edit without saving':'Let this draft go'}</button><p class="small">Your draft stays only in this open page until you save. Reloading clears unsaved words.</p>${personalNotice()}<div class="divider"></div><h2>Come back in your own time.</h2><label class="field" for="mind-search">Find a thought</label><input id="mind-search" type="search" value="${esc(mindQuery)}" placeholder="A word, title, or feeling…"><label class="field" for="mind-filter">Show</label><select id="mind-filter" class="section-select"><option value="any">All thoughts</option>${AntarPersonal.buckets.map(b=>`<option ${mindFilter===b?'selected':''}>${b}</option>`).join('')}</select><div id="mind-results">${personalReady?mindCards():'<p class="small">Opening your saved space…</p>'}</div><a class="install-link" href="#comfort">Visit my comfort shelf</a>${personalBackupControls()}`}
const shelfTypes=[['words','Comforting words'],['song','A song or helpful link'],['photo','A photo'],['audio','A voice note / audio file'],['person','Someone I can reach out to']];
function personalMediaURL(item){if(!personalURLs.has(item.id))personalURLs.set(item.id,URL.createObjectURL(item.file));return personalURLs.get(item.id)}
function comfortCard(item,compact=false){let media='';if(item.kind==='photo'&&item.file)media=`<img class="comfort-photo" src="${personalMediaURL(item)}" alt="${esc(item.title)}" loading="lazy">`;if(item.kind==='audio'&&item.file)media=`<audio controls preload="none" src="${personalMediaURL(item)}" aria-label="${esc(item.title)}"></audio>`;const link=AntarPersonal.safeLink(item.link||'');return `<article class="comfort-card"><p class="small">${esc(shelfTypes.find(t=>t[0]===item.kind)?.[1]||'Your comfort item')}${item.need?' · Chosen for '+esc(needLabel(item.need)):''}</p><h3>${esc(item.title)}</h3>${media}${item.text?`<p class="mind-body">${esc(item.text)}</p>`:''}${link?`<a class="install-link" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open your link ↗</a>`:''}<div class="chips">${item.kind==='words'?`<button class="text-btn" data-revisit-toggle="${esc(item.id)}">${item.revisit?'Remove from resurfacing':'Choose for resurfacing'}</button>`:''}<button class="text-btn" data-comfort-try="${esc(item.id)}">Try this &amp; check in after</button>${compact?'':`<button class="text-btn" data-personal-remove="${esc(item.id)}">Remove</button>`}</div></article>`}
function comfortPanel(){const all=personalItems.filter(x=>shelfTypes.some(t=>t[0]===x.kind)).sort((a,b)=>Date.parse(a.createdAt)-Date.parse(b.createdAt)),matched=all.filter(x=>feltNeed&&x.need===feltNeed),shown=(matched.length?matched:all).slice(-2).reverse();return `<section class="past-help"><h2>Your comfort shelf</h2>${shown.length?`<p class="small">${matched.length?'Items you chose for this need.':'A few things you chose to keep. You decide what fits today.'}</p>${shown.map(x=>comfortCard(x,true)).join('')}`:'<p class="sub">A familiar song, a photo, a few words, or someone to reach out to.</p>'}<a class="install-link" href="#comfort">Open my comfort shelf</a></section>`}
function comfortShelf(){return `<a class="install-link" href="#home">‹ Home</a><h1>Jo apna sa lage.</h1>${resurfaceCard()}<p class="sub">Your comfort shelf. Something familiar, without a task to complete.</p>${personalNotice()}<div class="chips">${shelfTypes.map(([id,label])=>`<button class="chip ${shelfType===id?'selected':''}" data-shelf-type="${id}" aria-pressed="${shelfType===id}">${label}</button>`).join('')}</div><label class="field" for="shelf-title">A name for this</label><input id="shelf-title" type="text" maxlength="100" value="${esc(shelfTitle)}" placeholder="For example: a message from my friend"><label class="field" for="shelf-text">${shelfType==='person'?'Their details and what you might say':'Words to keep with it'} <span class="small">(optional)</span></label><textarea id="shelf-text" maxlength="1200" placeholder="Jo tumhe yaad rakhna hai…">${esc(shelfText)}</textarea>${shelfType==='song'?`<label class="field" for="shelf-link">HTTPS link</label><input id="shelf-link" type="url" maxlength="2000" value="${esc(shelfLink)}" placeholder="https://…"><p class="small">The link opens only when you tap it. No embedded player or background requests.</p>`:''}${['photo','audio'].includes(shelfType)?`<label class="field" for="shelf-file">${shelfType==='photo'?'Choose a photo (JPEG, PNG, or WebP; up to 5 MB)':'Choose a voice note or audio file (up to 10 MB)'}</label><input id="shelf-file" type="file" accept="${shelfType==='photo'?'image/jpeg,image/png,image/webp':'audio/*'}"><p class="small" id="shelf-file-status">${shelfFile?esc(shelfFile.name)+' selected':'File stays on this device. Nothing is uploaded. Audio is selected from your files; Antar does not turn on your microphone.'}</p>`:''}<label class="field" for="shelf-need">Useful for a need? <span class="small">(optional, chosen by you)</span></label><select id="shelf-need" class="section-select">${needOptions(shelfNeed,false)}</select><button class="primary" data-personal="save-comfort" ${shelfBusy||!personalReady?'disabled':''}>${shelfBusy?'Saving…':'Keep on my comfort shelf'}</button><div class="divider"></div><h2>Your familiar things</h2>${personalReady?personalItems.filter(x=>shelfTypes.some(t=>t[0]===x.kind)).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt)).map(x=>comfortCard(x)).join('')||'<p class="empty">There’s room here. Add something only if it feels useful.</p>':'<p class="small">Opening your shelf…</p>'}<a class="install-link" href="#mind">Open my second mind</a>${personalBackupControls()}`}
function resetMindDraft(){mindText='';mindTitle='';mindBucket='Unsorted';mindEditing=null}
async function saveMindThought(){if(mindBusy)return;if(!mindText.trim())return toast('A few words first, or let the draft go.');mindBusy=true;try{const now=new Date().toISOString(),item={...(mindEditing||{}),id:mindEditing?.id||personalId(),kind:'thought',text:mindText.trim(),title:mindTitle.trim(),bucket:mindBucket,createdAt:mindEditing?.createdAt||now,updatedAt:now};await writePersonal(item,mindEditing?.updatedAt??null);resetMindDraft();await refreshPersonal(true);toast('Saved to your second mind.')}catch(error){toast(error.message||'Could not save. Your draft is still here.')}finally{mindBusy=false;render(true)}}
async function saveComfort(){if(shelfBusy)return;if(!shelfTitle.trim())return toast('Give this a name to find it later.');if(shelfType==='song'&&!AntarPersonal.safeLink(shelfLink))return toast('Use a complete HTTPS link without a username or password.');if(['photo','audio'].includes(shelfType)&&!shelfFile)return toast('Choose a file first.');if(shelfType==='words'&&!shelfText.trim())return toast('Add the words you want to keep.');shelfBusy=true;try{const current=await readPersonal(),size=current.reduce((sum,x)=>sum+(x.file?.size||0),0);if(size+(shelfFile?.size||0)>30*1024*1024)throw Error('Your shelf has reached its 30 MB media limit. Export it, then remove a file to make room.');const now=new Date().toISOString();await writePersonal({id:personalId(),kind:shelfType,title:shelfTitle.trim(),text:shelfText.trim(),link:shelfType==='song'?AntarPersonal.safeLink(shelfLink):'',need:shelfNeed,file:['photo','audio'].includes(shelfType)?shelfFile:null,createdAt:now,updatedAt:now});shelfTitle='';shelfText='';shelfLink='';shelfNeed='';shelfFile=null;await refreshPersonal(true);toast('Kept on your comfort shelf.')}catch(error){toast(error.message||'Could not save. Your words are still here.')}finally{shelfBusy=false;render(true)}}
async function exportPersonal(){try{const items=await readPersonal(),encoded=[];for(const item of items){const {file,...rest}=item;if(file)rest.media=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name||'media',type:file.type,dataURL:reader.result});reader.onerror=reject;reader.readAsDataURL(file)});encoded.push(rest)}const url=URL.createObjectURL(new Blob([JSON.stringify({format:'antar-personal-v1',exportedAt:new Date().toISOString(),items:encoded},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='antar-personal-'+AntarPatterns.dateKey(new Date())+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{toast('Could not export this shelf. Existing saved items remain on this device.')}}
document.addEventListener('input',event=>{const e=event.target;if(e.id==='mind-text')mindText=e.value;if(e.id==='mind-title')mindTitle=e.value;if(e.id==='mind-search'){mindQuery=e.value;$('#mind-results').innerHTML=mindCards()}if(e.id==='shelf-title')shelfTitle=e.value;if(e.id==='shelf-text')shelfText=e.value;if(e.id==='shelf-link')shelfLink=e.value});
document.addEventListener('change',event=>{const e=event.target;if(e.id==='mind-bucket')mindBucket=e.value;if(e.id==='mind-filter'){mindFilter=e.value;$('#mind-results').innerHTML=mindCards()}if(e.id==='shelf-need')shelfNeed=e.value;if(e.id==='shelf-file'){const file=e.files?.[0];shelfFile=null;if(!file)return;const photo=shelfType==='photo',valid=photo?['image/jpeg','image/png','image/webp'].includes(file.type):file.type.startsWith('audio/');if(!valid||file.size>(photo?5:10)*1024*1024){e.value='';$('#shelf-file-status').textContent='Choose a supported '+(photo?'photo up to 5 MB.':'audio file up to 10 MB.');return}shelfFile=file;$('#shelf-file-status').textContent=file.name+' selected; not saved yet.'}});
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;try{if(el.dataset.shelfType){shelfType=el.dataset.shelfType;shelfFile=null;render(true);return}if(el.dataset.mindEdit){const item=personalItems.find(x=>x.id===el.dataset.mindEdit);if(!item)return;if(mindText.trim()&&!confirm('Replace the open draft with this saved thought? Unsaved words will be lost.'))return;mindEditing={...item};mindText=item.text;mindTitle=item.title;mindBucket=item.bucket;if(route!=='mind')go('mind');else render();return}if(el.dataset.personalPin){const item=personalItems.find(x=>x.id===el.dataset.personalPin);await writePersonal({...item,pinned:!item.pinned,updatedAt:new Date().toISOString()},item.updatedAt);await refreshPersonal(true);return}if(el.dataset.personalRemove){const item=personalItems.find(x=>x.id===el.dataset.personalRemove);lastPersonalGroup=await removePersonalGroup(item);lastPersonalRemoval=item;if(personalURLs.has(item.id)){URL.revokeObjectURL(personalURLs.get(item.id));personalURLs.delete(item.id)}await refreshPersonal(true);toast('Removed. Undo is available below until you leave this page.');return}if(el.dataset.comfortTry){const item=personalItems.find(x=>x.id===el.dataset.comfortTry);if(item){startGentleAttempt(item.kind==='person'?'connection':'other',item.title,{comfortId:item.id});go('after')}return}switch(el.dataset.personal){case'save-thought':await saveMindThought();break;case'release-draft':if(mindText.trim()&&!confirm('Let go of this unsaved draft? Saved thoughts stay in your second mind.'))return;resetMindDraft();render(true);break;case'save-comfort':await saveComfort();break;case'export':await exportPersonal();break;case'refresh':await refreshPersonal();break;case'undo':if(lastPersonalRemoval){await restorePersonalGroup(lastPersonalGroup.length?lastPersonalGroup:[lastPersonalRemoval]);lastPersonalRemoval=null;lastPersonalGroup=[];await refreshPersonal(true);toast('Restored.')}break;}}catch(error){toast(error.message||'Could not change this item. Your saved data has not been replaced.')}});
